schema_ddl:
DROP TABLE IF EXISTS retribuzioni;
DROP TABLE IF EXISTS dipendenti;

CREATE TABLE dipendenti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome TEXT NOT NULL,
    cognome TEXT NOT NULL,
    codice_fiscale TEXT NOT NULL UNIQUE,
    data_assunzione DATE NOT NULL,
    email_aziendale TEXT UNIQUE
);

CREATE TABLE retribuzioni (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    dipendente_id INT NOT NULL UNIQUE REFERENCES dipendenti(id) ON DELETE CASCADE,
    stipendio_base NUMERIC(10,2) NOT NULL CHECK (stipendio_base >= 0),
    bonus_annuo NUMERIC(10,2) NOT NULL DEFAULT 0 CHECK (bonus_annuo >= 0),
    valuta TEXT NOT NULL DEFAULT 'EUR',
    data_decorrenza DATE NOT NULL,
    CHECK (stipendio_base + bonus_annuo > 0)
);
